import tempfile
import unittest
import zipfile
from pathlib import Path
from scripts.build_bootanimation import package

def tiny_png(width=1, height=1):
    # Header is enough for the format/dimension validation (real frames are generated by an editor).
    return b"\x89PNG\r\n\x1a\n" + b"\x00\x00\x00\rIHDR" + width.to_bytes(4,"big") + height.to_bytes(4,"big")

class BootAnimationTests(unittest.TestCase):
    def test_order_and_descriptor(self):
        with tempfile.TemporaryDirectory() as d:
            root = Path(d)
            for n in [2, 0, 1]:
                (root / f"{n}.png").write_bytes(tiny_png())
            output = root / "animation.zip"
            self.assertEqual(package(root, output, 1, 1, 30), 3)
            with zipfile.ZipFile(output) as z:
                self.assertEqual(z.read("desc.txt"), b"1 1 30\np 0 0 part0\n")
                self.assertEqual(z.namelist()[1:], [f"part0/{i:05d}.png" for i in range(3)])

    def test_missing_frame_is_error(self):
        with tempfile.TemporaryDirectory() as d:
            root = Path(d)
            (root / "0.png").write_bytes(tiny_png())
            (root / "2.png").write_bytes(tiny_png())
            with self.assertRaises(ValueError):
                package(root, root / "out.zip", 1, 1, 30)

if __name__ == "__main__":
    unittest.main()
